<?php $h=fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');$label=fn($s)=>match($s){'CONFORMING'=>'Conforme','NONCONFORMING'=>'Fora da especificação','NO_SPECIFICATION'=>'Sem especificação aplicável',default=>'Não avaliado'};require dirname(__DIR__).'/layouts/admin_start.php';?>
<a class="button button-secondary" href="javascript:history.back()">Voltar ao relatório</a><section class="content-card qcr-detail"><h2>Dados da amostra</h2><dl><?php foreach([['Nº da doação',$sample['donation_number']],['Código LCQH',$sample['lcqh_code']],['Hemocomponente',$sample['component_code'].' — '.$sample['component_name']],['Origem',$sample['origin_name']],['Recebimento',$sample['received_at']?date('d/m/Y H:i',strtotime($sample['received_at'])):'—'],['Produção',$sample['production_date']?date('d/m/Y',strtotime($sample['production_date'])):'—'],['Bolsa',trim(($sample['bag_brand']??'').' · '.($sample['reference_number']??''),' ·')],['Preservante',$sample['preservative_name']]]as[$k,$v]):?><div><dt><?=$h($k)?></dt><dd><?=$h($v?:'—')?></dd></div><?php endforeach;?></dl></section>
<section class="content-card qcr-detail"><h2>Resultados finais vigentes</h2><div class="qcr-table-scroll"><table><thead><tr><th>Teste</th><th>Resultado</th><th>Referência histórica</th><th>Conformidade</th><th>Data/hora</th><th>Responsável</th><th>Ocorrência</th></tr></thead><tbody><?php foreach($sample['results']as$r):?><tr><td><?=$h($r['name'])?></td><td><span class="qcr-result <?=$r['status']==='NONCONFORMING'?'is-out':''?>"><?=$h($r['display'])?></span></td><td><?=$h($r['reference'])?></td><td><?=$h($label($r['status']))?></td><td><?=$r['recorded_at']?date('d/m/Y H:i',strtotime($r['recorded_at'])):'—'?></td><td><?=$h($r['recorded_by']?:'—')?></td><td><?php if($canViewNotifications&&$r['notification_id']):?><a href="/notifications?id=<?=$r['notification_id']?>">Notificação <?=$h($r['notification_code'])?></a><?php else:?>—<?php endif;?></td></tr><?php endforeach;?></tbody></table></div><p class="qcr-readonly">Consulta somente leitura. Correções e histórico permanecem na auditoria administrativa.</p></section>
